require('dotenv').config();
const express = require('express');

const app  = express();
const PORT = process.env.PORT || 3000;
const startTime = Date.now();

app.use(express.json());

// ── Health check endpoint ──
// Load balancers, Docker, Kubernetes all use this
app.get('/health', (req, res) => {
    res.json({
        status:  'ok',
        uptime:  Math.floor((Date.now() - startTime) / 1000) + 's',
        version: process.env.npm_package_version || '?',
        env:     process.env.NODE_ENV || 'development',
    });
});

// ── Ready check (separate from health) ──
// Returns 503 until DB connection is established
let isReady = false;
app.get('/ready', (req, res) => {
    if (!isReady) return res.status(503).json({ status: 'not ready' });
    res.json({ status: 'ready' });
});

// Your routes here...
app.get('/', (req, res) => res.json({ message: 'Hello World' }));

// ── Start server ──
const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${process.env.NODE_ENV})`);
    isReady = true;  // Mark ready after startup
});

// ── Graceful shutdown ──
function gracefulShutdown(signal) {
    console.log(`${signal} received. Shutting down gracefully...`);
    server.close(() => {
        console.log('HTTP server closed. Exiting.');
        process.exit(0);
    });
    // Force shutdown after 10s if server doesn't close
    setTimeout(() => process.exit(1), 10_000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT',  () => gracefulShutdown('SIGINT'));
